    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: Which mnemonic is commonly used to remember the causes of High Anion Gap Metabolic Acidosis (HAGMA)?', '["MUDPILES", "HARDUPS", "WINTERS", "ABCD"]', 0, 'MUDPILES: Methanol, Uremia, DKA, Propylene glycol, Iron/Isoniazid, Lactic acid, Ethylene glycol, Salicylates.'),
    (v_topic_id, '102: The mnemonic "GOLDMARK" is a newer alternative for HAGMA. What does the "G" stand for?', '["Glucose", "Glycols (Ethylene and Propylene)", "Glutamate", "Guanidine"]', 1, 'GOLDMARK: Glycols, Oxoproline, L-lactate, D-lactate, Methanol, Aspirin, Renal failure, Ketoacidosis.'),
    (v_topic_id, '103: In "Metabolic Acidosis," the respiratory compensation (hyperventilation) begins within:', '["Seconds", "Minutes", "Days", "Weeks"]', 1, 'The respiratory center responds quickly to changes in arterial pH.'),
    (v_topic_id, '104: The maximum respiratory compensation in metabolic acidosis rarely lowers the pCO2 below:', '["30 mmHg", "20 mmHg", "10 mmHg", "5 mmHg"]', 2, 'The limit of respiratory compensation is usually around 10-15 mmHg.'),
    (v_topic_id, '105: "Hypovolemic Shock" is a classic cause of which type of Lactic Acidosis?', '["Type A", "Type B", "Type C", "Type D"]', 0, 'Inadequate perfusion leads to anaerobic metabolism and L-lactate production.'),
    (v_topic_id, '106: "Metformin" can cause Type B Lactic Acidosis by inhibiting:', '["The Krebs cycle", "Mitochondrial respiration and gluconeogenesis", "Glycolysis", "The lungs"]', 1, 'It interferes with the liver''s ability to clear lactate.'),
    (v_topic_id, '107: "Cyanide Poisoning" causes HAGMA by:', '["Blocking the electron transport chain (Cytochrome c oxidase)", "Causing diarrhea", "Kidney failure", "Liver failure"]', 0, 'This prevents cells from using oxygen, forcing anaerobic metabolism even in the presence of O2.'),
    (v_topic_id, '108: A patient with a HAGMA and Optic Disc Hyperemia (redness) likely ingested:', '["Ethylene glycol", "Methanol", "Aspirin", "Tylenol"]', 1, 'Formic acid is specifically toxic to the retina and optic nerve.'),
    (v_topic_id, '109: A patient with a HAGMA and Calcium Oxalate crystals in the urine likely ingested:', '["Methanol", "Ethylene glycol", "Isopropyl alcohol", "Propylene glycol"]', 1, 'Ethylene glycol metabolism produces oxalic acid, which binds calcium.'),
    (v_topic_id, '110: "High Anion Gap" without an obvious cause should prompt testing for "5-oxoproline" if the patient is on:', '["Chronic high-dose Acetaminophen", "Insulin", "Penicillin", "Diuretics"]', 0, 'This is also known as Pyroglutamic acidosis.'),
    (v_topic_id, '111: "Propylene Glycol" is the solvent for which commonly used IV sedative?', '["Propofol", "Lorazepam", "Midazolam", "Ketamine"]', 1, 'High doses of IV Lorazepam in the ICU can lead to HAGMA and an elevated osmolar gap.'),
    (v_topic_id, '112: In "Uremic Acidosis," the Anion Gap increases because of the retention of:', '["Urea", "Creatinine", "Phosphate, Sulfate, and organic acids", "Sodium"]', 2, 'These are the "unmeasured anions" that accumulate as GFR falls.'),
    (v_topic_id, '113: Which mnemonic is used for the causes of Normal Anion Gap Metabolic Acidosis (NAGMA)?', '["MUDPILES", "HARDUPS", "GOLDFISH", "STAIRS"]', 1, 'HARDUPS: Hyperalimentation, Acetazolamide, RTA, Diarrhea, Ureteroenteric fistula, Pancreatic fistula, Spironolactone/Saline.'),
    (v_topic_id, '114: "Hyperalimentation" (TPN) causes NAGMA primarily due to:', '["High glucose", "Excessive administration of Chloride-rich amino acids", "Fatty acids", "Vitamin toxicity"]', 1, 'Metabolism of these amino acids yields HCl.'),
    (v_topic_id, '115: "Diarrhea" causes NAGMA due to the loss of:', '["HCl", "Sodium Chloride", "Bicarbonate", "Potassium only"]', 2, 'Lower GI secretions are rich in HCO3-.'),
    (v_topic_id, '116: "Renal Tubular Acidosis" (RTA) always presents as a:', '["HAGMA", "NAGMA", "Respiratory Acidosis", "Metabolic Alkalosis"]', 1, 'RTAs are defects in bicarbonate handling or acid excretion that do not involve the accumulation of new anions.'),
    (v_topic_id, '117: Which RTA is associated with Nephrolithiasis (Kidney Stones)?', '["Type 1 (Distal)", "Type 2 (Proximal)", "Type 4", "None of them"]', 0, 'High urine pH and hypercalciuria promote calcium phosphate stone formation.'),
    (v_topic_id, '118: Which RTA is caused by Aldosterone deficiency or resistance?', '["Type 1", "Type 2", "Type 4 (Hyperkalemic RTA)", "Type 3"]', 2, 'Common causes include Diabetes (Hyporeninemic hypoaldosteronism) and drugs like ACE inhibitors or Spironolactone.'),
    (v_topic_id, '119: A patient with pH 7.28, HCO3 14, and pCO2 29 has:', '["Metabolic Acidosis with appropriate compensation", "Metabolic Acidosis with secondary Respiratory Acidosis", "Mixed Metabolic and Respiratory Alkalosis", "Respiratory Acidosis"]', 0, 'Using Winter''s formula: (1.5 * 14) + 8 = 29. The pCO2 matches the expected value.'),
    (v_topic_id, '120: A patient with pH 7.20, HCO3 10, and pCO2 40 has:', '["Metabolic Acidosis and Respiratory Acidosis (Mixed)", "Pure Metabolic Acidosis", "Pure Respiratory Acidosis", "Metabolic Acidosis with over-compensation"]', 0, 'Expected pCO2 by Winter''s is 23. Since the actual pCO2 is 40, there is a severe secondary respiratory acidosis (failure to hyperventilate).'),
    (v_topic_id, '121: "Metabolic Alkalosis" is commonly initiated by the loss of _____ from the stomach.', '["Hydrogen and Chloride", "Bicarbonate", "Sodium", "Lactic acid"]', 0, 'HCl loss leaves the body with an excess of HCO3.'),
    (v_topic_id, '122: "Contraction Alkalosis" occurs when:', '["The body loses volume that is poor in bicarbonate (like with diuretics), concentrating the remaining HCO3", "The heart stops", "The patient is overhydrated", "Sodium is high"]', 0, 'Loss of NaCl and water causes the extracellular fluid volume to shrink around a fixed amount of bicarbonate.'),
    (v_topic_id, '123: "Hypokalemia" contributes to metabolic alkalosis by:', '["Shifting H+ into cells and stimulating H+ secretion in the distal tubule", "Causing diarrhea", "Increasing CO2", "Lowering pH"]', 0, 'As K+ leaves cells to correct serum levels, H+ enters cells. Also, the kidney "trades" H+ for Na+ when K+ is scarce.'),
    (v_topic_id, '124: "Urine Chloride" < 10-20 mEq/L in metabolic alkalosis suggests the patient is:', '["Volume expanded", "Volume depleted (Chloride-responsive)", "Taking diuretics currently", "In renal failure"]', 1, 'The kidney is avidly reabsorbing sodium and chloride to restore volume.'),
    (v_topic_id, '125: "Urine Chloride" > 20 mEq/L in metabolic alkalosis suggests the patient is:', '["Volume expanded or has a genetic tubular defect (Chloride-resistant)", "Dehydrated", "Healthy", "Anemic"]', 0, 'Common in Primary Hyperaldosteronism or current diuretic use.'),
    (v_topic_id, '126: "Hypercapnia" (elevated pCO2) is the hallmark of:', '["Metabolic Acidosis", "Respiratory Acidosis", "Metabolic Alkalosis", "Respiratory Alkalosis"]', 1, 'It is caused by alveolar hypoventilation.'),
    (v_topic_id, '127: "Acute on Chronic" Respiratory Acidosis is seen when a patient with stable COPD:', '["Improves", "Develops an acute illness (e.g., Pneumonia) that further impairs ventilation", "Stops smoking", "Exercises"]', 1, 'The pH drops acutely because the kidneys cannot compensate fast enough for the new rise in CO2.'),
    (v_topic_id, '128: "Respiratory Alkalosis" is the most common acid-base disturbance in which condition?', '["Early Pregnancy", "Renal failure", "COPD", "Diabetes"]', 0, 'Progesterone stimulates the respiratory center, leading to a chronic, mild respiratory alkalosis.'),
    (v_topic_id, '129: "High Altitude" causes Respiratory Alkalosis because:', '["The air is cold", "Low partial pressure of O2 stimulates the carotid bodies to increase ventilation", "Pressure is high", "CO2 is high in the air"]', 1, 'Hypoxia-induced hyperventilation.'),
    (v_topic_id, '130: "Salicylate Toxicity" causes Respiratory Alkalosis by:', '["Directly stimulating the medullary respiratory center", "Causing lung edema", "Paralyzing the diaphragm", "Inhibiting the heart"]', 0, 'This is a primary, centrally-mediated hyperventilation.'),
    (v_topic_id, '131: "Anion Gap" = 22, HCO3 = 10. Normal AG = 12. What is the Delta-Delta?', '["1.0", "0.8", "1.2", "2.0"]', 0, '\u0394AG = 22 - 12 = 10. \u0394HCO3 = 24 - 10 = 14. Ratio = 10/14 \u2248 0.7. This suggests a mixed HAGMA and NAGMA.'),
    (v_topic_id, '132: "Anion Gap" = 25, HCO3 = 28. Normal AG = 10. What is the Delta-Delta?', '["1.5", "1.0", "1.1", "Greater than 2.0"]', 3, '\u0394AG = 15. \u0394HCO3 = -4 (it actually ROSE). Ratio is very high, suggesting HAGMA + Metabolic Alkalosis.'),
    (v_topic_id, '133: A patient with chronic COPD has pCO2 60 and HCO3 30. What is the pH?', '["Very acidotic (< 7.20)", "Mildly acidotic (around 7.32)", "Alkalotic", "Normal (7.40)"]', 1, 'The kidneys have compensated by raising the HCO3, but the pH remains on the acid side of normal.'),
    (v_topic_id, '134: A patient has pH 7.55, pCO2 25, HCO3 22. This is:', '["Acute Respiratory Alkalosis", "Chronic Respiratory Alkalosis", "Metabolic Alkalosis", "Metabolic Acidosis"]', 0, 'The HCO3 is near normal, indicating the kidneys haven''t had time to compensate yet.'),
    (v_topic_id, '135: A patient has pH 7.44, pCO2 25, HCO3 16. This is:', '["Acute Respiratory Alkalosis", "Chronic Respiratory Alkalosis", "Metabolic Acidosis", "Metabolic Alkalosis"]', 1, 'The pH is near normal due to significant renal compensation (dropping the HCO3).'),
    (v_topic_id, '136: "Pseudohyponatremia" (due to high lipids or proteins) does NOT affect:', '["The Anion Gap", "The Osmolar Gap (it remains normal if measured by freezing point)", "Calculated Osmolality", "pH"]', 1, 'Measured osmolality by freezing point depression is unaffected by the volume-occupying effect of lipids.'),
    (v_topic_id, '137: "Post-Hypercapnic Metabolic Alkalosis" occurs when a patient with Chronic Respiratory Acidosis is:', '["Put on a ventilator and their pCO2 is lowered too rapidly", "Given oxygen", "Allowed to sleep", "Dehydrated"]', 0, 'The kidneys had a high HCO3 to compensate for pCO2 60; if pCO2 is suddenly 40, the high HCO3 now causes alkalosis.'),
    (v_topic_id, '138: "Chloride-Depletion Alkalosis" is a synonym for:', '["Saline-responsive metabolic alkalosis", "Saline-resistant alkalosis", "NAGMA", "Respiratory Alkalosis"]', 0, 'Chloride is necessary for the kidney to excrete bicarbonate.'),
    (v_topic_id, '139: In "Chronic Renal Failure," the most common initial acid-base disturbance is:', '["Metabolic Alkalosis", "NAGMA (due to decreased ammonia production)", "HAGMA", "Respiratory Acidosis"]', 1, 'As GFR falls from 50 to 20, NAGMA is common; below 20, HAGMA develops.'),
    (v_topic_id, '140: A "Hidden" acid-base disorder can be found by calculating the:', '["pO2", "Anion Gap in every patient, regardless of pH", "K+", "BUN"]', 1, 'You can have a high anion gap even if the pH and HCO3 are perfectly normal (if a simultaneous alkalosis exists).'),
    (v_topic_id, '141: "Ketosis" without "Acidosis" is characteristic of:', '["DKA", "Isopropyl Alcohol ingestion", "Starvation", "Vomiting"]', 1, 'Metabolism of isopropyl alcohol produces acetone (a ketone) but no acid.'),
    (v_topic_id, '142: "Ethylene Glycol" is often found in:', '["Antifreeze", "Window cleaner", "Paint", "Perfume"]', 0, 'Accidental or intentional ingestion is a common cause of severe HAGMA.'),
    (v_topic_id, '143: "Methanol" is often found in:', '["Windshield washer fluid and \"moonshine\"", "Antifreeze", "Bread", "Beer"]', 0, 'Contaminated illicit alcohol is a classic source.'),
    (v_topic_id, '144: "Fomepizole" is the antidote for Methanol and Ethylene Glycol. It works by:', '["Neutralizing the acid", "Inhibiting Alcohol Dehydrogenase", "Stimulating the kidneys", "Blocking the heart"]', 1, 'It prevents the conversion of the alcohols into their toxic acidic metabolites.'),
    (v_topic_id, '145: "Ethanol" can also be used as an antidote for Methanol because it:', '["Is a base", "Has a higher affinity for Alcohol Dehydrogenase, competing with the toxins", "Neutralizes formic acid", "Is more toxic"]', 1, 'Fomepizole is preferred but ethanol is an alternative in resource-limited settings.'),
    (v_topic_id, '146: "Ketoacids" are "Unmeasured Anions." When DKA is treated with insulin, the ketones are converted to:', '["Glucose", "Bicarbonate", "Lactic acid", "CO2 only"]', 1, 'As ketones are metabolized, HCO3 is regenerated, which is why aggressive IV HCO3 is usually NOT needed in DKA.'),
    (v_topic_id, '147: Aggressive fluid resuscitation in DKA often causes the HAGMA to transition into a:', '["Metabolic Alkalosis", "NAGMA (Hyperchloremic acidosis)", "Respiratory Acidosis", "Normal state"]', 1, 'Loss of ketones in the urine and administration of large amounts of saline lead to hyperchloremia.'),
    (v_topic_id, '148: A "Negative" Osmolar Gap is:', '["Impossible", "A sign of laboratory error", "Common in healthy people", "A sign of renal failure"]', 1, 'It suggests a mistake in the measured osmolality or the calculated formula.'),
    (v_topic_id, '149: "Lactate" can be elevated in which non-hypoxic state?', '["Severe exercise", "Seizures", "Beta-agonist use (e.g., Albuterol)", "All of the above"]', 3, 'These increase the rate of glycolysis beyond the capacity of the mitochondria.'),
    (v_topic_id, '150: "Propofol Infusion Syndrome" is characterized by:', '["Metabolic Alkalosis", "Lactic Acidosis, Bradycardia, and Rhabdomyolysis", "Pneumonia", "High sugar"]', 1, 'This is a rare but fatal complication of high-dose, long-term propofol infusion.'),
    (v_topic_id, '151: "Iron Toxicity" causes HAGMA by:', '["Damaging the liver", "Disrupting mitochondrial function and causing shock", "Loss of blood", "Renal failure"]', 1, 'It is a common pediatric poisoning.'),
    (v_topic_id, '152: "Isoniazid (INH)" toxicity causes HAGMA and:', '["Blindness", "Seizures (refractory to standard treatment, requiring Pyridoxine)", "Deafness", "Heart failure"]', 1, 'INH inhibits GABA synthesis, leading to status epilepticus.'),
    (v_topic_id, '153: "Toluene" (glue sniffing) classically causes which acid-base disturbance?', '["Pure HAGMA", "NAGMA (due to hippurate excretion)", "Metabolic Alkalosis", "Respiratory Acidosis"]', 1, 'While hippurate is an anion, it is excreted so rapidly by the kidney that the AG often remains normal.'),
    (v_topic_id, '154: "Hyperchloremic Acidosis" after major surgery is usually due to:', '["Pneumonia", "Excessive administration of 0.9% Normal Saline", "Renal failure", "Pain"]', 1, 'The high chloride content of saline "displaces" bicarbonate.'),
    (v_topic_id, '155: "Uretero-sigmoidostomy" (implanting ureters into the colon) causes NAGMA because:', '["The colon absorbs chloride and secretes bicarbonate in exchange for urine", "The patient can''t pee", "The colon is acidic", "Metabolism changes"]', 0, 'This procedure is now rarely performed but is a classic boards question.'),
    (v_topic_id, '156: "Spironolactone" can cause a Type 4 RTA by:', '["Blocking aldosterone receptors in the distal tubule", "Damaging the glomerulus", "Causing diarrhea", "Bicarbonate loss"]', 0, 'This leads to K+ retention and H+ retention.'),
    (v_topic_id, '157: "Amphotericin B" is a classic cause of which RTA?', '["Type 1 (Distal)", "Type 2", "Type 4", "None"]', 0, 'It makes the distal tubule membrane "leaky," preventing the maintenance of a hydrogen ion gradient.'),
    (v_topic_id, '158: "Multiple Myeloma" is a common cause of which RTA?', '["Type 1", "Type 2 (Proximal)", "Type 4", "Type 3"]', 1, 'Light chains are toxic to the proximal tubular cells.'),
    (v_topic_id, '159: "Sj\u00f6gren Syndrome" is associated with which RTA?', '["Type 1 (Distal)", "Type 2", "Type 4", "None"]', 0, 'Autoimmune damage to the distal intercalated cells.'),
    (v_topic_id, '160: A patient with HAGMA and an AG of 35 is most likely to have:', '["DKA", "Lactic Acidosis", "Methanol or Ethylene Glycol toxicity", "Salicylate toxicity"]', 2, 'Gaps > 30 are most commonly seen in the toxic alcohols and severe lactic acidosis.'),
    (v_topic_id, '161: The "Stewart" approach considers which of the following as a WEAK acid?', '["Chloride", "Albumin and Phosphate", "Sodium", "Carbon dioxide"]', 1, 'These are called "A_tot."'),
    (v_topic_id, '162: "Metabolic Acidosis" can cause "Hyperkalemia" because:', '["H+ enters cells and K+ exits cells to maintain electrical balance", "The kidney stops excreting K+", "The heart fails", "Sugar rises"]', 0, 'This is most prominent in mineral acid (NAGMA) states.'),
    (v_topic_id, '163: "DKA" and "Lactic Acidosis" cause hyperkalemia primarily through:', '["H+/K+ exchange", "Insulin deficiency and hyperosmolality (DKA) or cell death/perfusion failure (Lactate)", "Kidney failure", "Breathing"]', 1, 'The H+/K+ shift is less significant for organic acidemias compared to mineral acidemias.'),
    (v_topic_id, '164: "Hyperventilation" (Respiratory Alkalosis) causes "Hypocalcemia" symptoms (numbness/tingling) because:', '["Calcium is lost in the urine", "Decreased H+ allows more Calcium to bind to Albumin, lowering the IONIZED calcium level", "Alkalosis stops the heart", "Calcium enters cells"]', 1, 'Total calcium is normal, but the active (ionized) fraction drops.'),
    (v_topic_id, '165: A patient with pH 7.50 and pCO2 50 has:', '["Metabolic Alkalosis with appropriate compensation", "Respiratory Acidosis", "Metabolic Alkalosis and Respiratory Alkalosis", "Normal ABG"]', 0, 'The pCO2 has risen to compensate for the primary metabolic alkalosis.'),
    (v_topic_id, '166: "Villard sign" is not an ABG term. Which of the following is a sign of severe acidosis?', '["Kussmaul breathing (deep, rapid respirations)", "Tachypnea", "Apnea", "Slow breathing"]', 0, 'This is the body''s attempt to blow off as much CO2 as possible.'),
    (v_topic_id, '167: Severe "Acidemia" (pH < 7.10) can lead to:', '["Increased heart contractility", "Decreased cardiac contractility and hypotension", "High blood pressure", "Seizures"]', 1, 'It also reduces the heart''s responsiveness to catecholamines (epinephrine).'),
    (v_topic_id, '168: "Intravenous Sodium Bicarbonate" is generally NOT recommended in:', '["DKA and Lactic Acidosis (Type A)", "TCA overdose", "Salicylate toxicity", "Severe hyperkalemia"]', 0, 'The underlying cause must be treated; HCO3 can cause paradoxical intracellular acidosis.'),
    (v_topic_id, '169: "Sodium Bicarbonate" IS indicated in:', '["Metabolic Alkalosis", "Severe NAGMA (pH < 7.20) or Salicylate toxicity (to alkalinize urine)", "Asthma", "Heart failure"]', 1, 'It helps promote the excretion of weak acids like salicylate.'),
    (v_topic_id, '170: "Contraction Alkalosis" is best treated with:', '["Normal Saline (0.9% NaCl)", "Sodium Bicarbonate", "Diuretics", "Water"]', 0, 'Restoring volume and chloride allows the kidney to excrete the excess bicarbonate.'),
    (v_topic_id, '171: "Acetazolamide" can be used to treat metabolic alkalosis in which specific group?', '["Patients with heart failure who cannot tolerate volume (Saline)", "Diabetics", "Asthmatics", "Athletes"]', 0, 'It forces the kidney to waste bicarbonate without requiring a fluid bolus.'),
    (v_topic_id, '172: "Hypokalemic, Hypochloremic Metabolic Alkalosis" is the classic acid-base pattern of:', '["Vomiting/Nasogastric suction", "Diarrhea", "Renal failure", "COPD"]', 0, 'This is the "Triple Threat" seen in bulimia or pyloric stenosis.'),
    (v_topic_id, '173: "Chloride-Resistant" alkalosis (High Urine Cl) is often due to:', '["Vomiting", "Mineralocorticoid excess (Primary Aldosteronism)", "Low salt diet", "Exercise"]', 1, 'The body is volume-expanded, so the kidney is not trying to save salt.'),
    (v_topic_id, '174: "Bartter Syndrome" affects which part of the nephron?', '["Proximal tubule", "Thick ascending limb of the Loop of Henle", "Distal tubule", "Collecting duct"]', 1, 'It is like a "genetic version of Lasix (Furosemide)."'),
    (v_topic_id, '175: "Gitelman Syndrome" affects which part of the nephron?', '["Loop of Henle", "Distal Convoluted Tubule", "Proximal tubule", "Glomerulus"]', 1, 'It is like a "genetic version of a Thiazide diuretic."'),
    (v_topic_id, '176: "Hypercalciuria" (high urine calcium) is common in Bartter syndrome but _____ is common in Gitelman syndrome.', '["Hypocalciuria (low urine calcium)", "Hypercalcemia", "Stones", "Low pH"]', 0, 'This mirrors the effect of Thiazides, which are used to prevent kidney stones by lowering urine calcium.'),
    (v_topic_id, '177: "Base Excess" of -15 suggests:', '["Severe Metabolic Alkalosis", "Severe Metabolic Acidosis", "Respiratory Acidosis", "Normal state"]', 1, 'Negative base excess is a base deficit.'),
    (v_topic_id, '178: A "Gap-Gap" ratio (Delta-Delta) of 1:1 is the expected finding in:', '["Mixed HAGMA/NAGMA", "Pure HAGMA", "Mixed HAGMA/Alkalosis", "Respiratory Acidosis"]', 1, 'For every mEq of unmeasured acid added, one mEq of bicarbonate is consumed.'),
    (v_topic_id, '179: Which organ produces "Lactate" under normal conditions?', '["Brain and RBCs", "Liver", "Spleen", "Lungs"]', 0, 'RBCs lack mitochondria and rely entirely on anaerobic metabolism.'),
    (v_topic_id, '180: "Lactate" is primarily cleared by the:', '["Kidneys", "Liver", "Lungs", "Skin"]', 1, 'Liver failure is a common cause of hyperlactatemia.'),
    (v_topic_id, '181: "Anion Gap" calculation should be done in every patient with:', '["A cough", "Metabolic Acidosis (low HCO3)", "Headache", "Fever"]', 1, 'This is the key first step in determining the etiology of the acidosis.'),
    (v_topic_id, '182: A "Low Anion Gap" (< 4) can be caused by:', '["Multiple Myeloma (due to cationic IgG)", "Hypermagnesemia or Hypercalcemia", "Severe Hypoalbuminemia", "All of the above"]', 3, 'High levels of positive ions (cations) or low levels of negative unmeasured anions (albumin) will reduce the gap.'),
    (v_topic_id, '183: "Hyperalbuminemia" (rare, usually due to severe dehydration) will cause the Anion Gap to:', '["Rise", "Fall", "Stay the same", "Disappear"]', 0, 'More unmeasured negative charges (albumin) increase the calculated gap.'),
    (v_topic_id, '184: "Ketoacids" are better detected by which method?', '["Urine dipstick (detects acetoacetate)", "Serum Beta-hydroxybutyrate (the predominant ketone in DKA)", "Standard Anion Gap", "Both B and C"]', 3, 'The dipstick often underestimates the severity of DKA.'),
    (v_topic_id, '185: "Metabolic Alkalosis" compensation involves the pCO2 increasing by approximately _____ for every 1 mEq/L rise in HCO3.', '["0.1 mmHg", "0.7 mmHg", "1.5 mmHg", "5.0 mmHg"]', 1, 'The body slows breathing to retain CO2, although this is limited by the drive to avoid hypoxia.'),
    (v_topic_id, '186: "Acute Respiratory Acidosis" usually results in a pH change of:', '["0.08 units per 10 mmHg pCO2 rise", "0.03 units per 10 mmHg pCO2 rise", "0.10 units", "No change"]', 0, 'This is more dramatic than the chronic state due to lack of renal compensation.'),
    (v_topic_id, '187: "Chronic Respiratory Acidosis" usually results in a pH change of:', '["0.08 units per 10 mmHg pCO2 rise", "0.03 units per 10 mmHg pCO2 rise", "0.15 units", "Zero"]', 1, 'Renal compensation blunts the pH drop.'),
    (v_topic_id, '188: "Acute Respiratory Alkalosis" usually results in a pH change of:', '["0.08 units per 10 mmHg pCO2 fall", "0.03 units per 10 mmHg pCO2 fall", "0.1 units", "No change"]', 0, 'Common in acute panic attacks.'),
    (v_topic_id, '189: "Chronic Respiratory Alkalosis" usually results in a pH change of:', '["0.08 units per 10 mmHg pCO2 fall", "0.03 units per 10 mmHg pCO2 fall", "0.01 units", "Zero"]', 1, 'Common in residents of high altitudes.'),
    (v_topic_id, '190: A "Mixed Venous Blood Gas" (from a central line) is particularly useful for assessing:', '["Oxygen saturation", "Tissue oxygen extraction and Cardiac Output", "Lung function", "pH"]', 1, 'Low mixed venous O2 saturation (SvO2) suggests high tissue extraction or low delivery (shock).'),
    (v_topic_id, '191: "Hyperphosphatemia" in renal failure will _____ the Anion Gap.', '["Increase", "Decrease", "Not change", "Hide"]', 0, 'Phosphate is an unmeasured anion.'),
    (v_topic_id, '192: "Hypercalcemia" will _____ the Anion Gap.', '["Increase", "Decrease", "Not change", "Mask"]', 1, 'Calcium is an unmeasured cation.'),
    (v_topic_id, '193: A patient with an "Arterialized" capillary gas has a pO2 that is:', '["Higher than arterial", "Close to arterial but slightly lower", "Higher than venous", "Both B and C"]', 3, 'Warming the skin helps "arterialize" the capillary bed.'),
    (v_topic_id, '194: "Base Deficit" is often used in trauma to estimate:', '["The amount of blood loss and the severity of shock", "Head injury", "Fractures", "Infection"]', 0, 'It is a surrogate for global tissue perfusion/lactic acidosis.'),
    (v_topic_id, '195: "Hypoxic vasoconstriction" is a lung response to:', '["High pO2", "Low Alveolar pO2 (P_A_O2)", "High pCO2", "Normal pH"]', 1, 'The lung shunts blood away from poorly ventilated areas.'),
    (v_topic_id, '196: "Permissive Hypercapnia" is a ventilation strategy used in ARDS where:', '["pCO2 is kept at 40", "pCO2 is allowed to rise to protect the lungs from high pressure (volutrauma)", "The patient is sedated", "HCO3 is low"]', 1, 'We accept a low pH to avoid damaging the lungs with the ventilator.'),
    (v_topic_id, '197: Which of the following is a potential complication of correcting "Chronic Respiratory Acidosis" too quickly?', '["Seizures and Arrhythmias (due to acute alkalosis)", "Pneumonia", "Renal failure", "Diabetes"]', 0, 'The patient becomes acutely alkalotic because their HCO3 is still high while CO2 is now normal.'),
    (v_topic_id, '198: "Acid-Base" balance is essential for the function of which vital molecules?', '["Proteins/Enzymes", "Fats", "Sugars", "Vitamins"]', 0, 'pH changes alter the charge and shape of proteins, potentially denaturing them.'),
